from pathlib import Path
import json,html
R=Path(__file__).resolve().parent
D=json.loads((R.parents[1]/'validation/regression/reports/bike_hour.json').read_text())
B=D['profile']['regression']['target_statistics']['histogram']['bins']
mark='<svg viewBox="0 0 32 32" aria-hidden="true"><path d="M2 28V4h7l14 16V4h7v24h-7L9 12v16Z" fill="currentColor"/></svg>'
rows=[(1,3,13,16),(2,8,32,40),(3,5,27,32),(4,3,10,13),(5,0,1,1)]
def table():
 return '<table class="source-table"><caption>Source examples / parsed row references</caption><thead><tr><th>Row</th><th>casual</th><th>registered</th><th>cnt</th></tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{x}</td>' for x in r)+'</tr>' for r in rows)+'</tbody></table>'
def plot():
 s='<svg class="histogram" viewBox="0 0 680 260" role="img" aria-label="Target cnt: 40 bins, 17,379 finite values; median 142. Counts on the vertical axis, target values on the horizontal axis.">'
 for v in [0,1000,2000,3000]:
  y=220-v/3500*180;s+=f'<path class="gridline" d="M38 {y}H664"/><text x="0" y="{y+3}">{v}</text>'
 for i,b in enumerate(B):
  h=b['count']/3500*180;s+=f'<rect class="histobar" x="{38+i*15.6}" y="{220-h}" width="12" height="{h}"><title>{b["lower"]:.1f}–{b["upper"]:.1f}: {b["count"]:,} rows</title></rect>'
 s+='<text x="38" y="245">1</text><text x="195" y="245">250</text><text x="350" y="245">500</text><text x="510" y="245">750</text><text x="642" y="245">977</text><text x="0" y="18">Rows</text></svg>'
 return s
P=plot();T=table()
def header(n):
 return f'<header class="site-header"><a class="brand" href="{n}.html" aria-label="NUMEK home">{mark}<span>numek</span></a><a class="product-name" href="#workspace">DataTrust</a><nav><a href="#approach">The approach</a><a class="nav-enter" href="#workspace">Explore the analysis <span>↗</span></a></nav></header>'
def workspace(n):
 title='<div class="work-title"><div><span>Dataset investigation</span><h2>Bike Sharing</h2><p>A closer look at the data behind the prediction.</p></div><span class="finding-count">4<small>findings to investigate</small></span></div>'
 chart=f'<div class="work-chart"><div class="chart-caption"><h3>The shape of the target</h3><span>cnt / rental bikes per interval</span></div>{P}<div class="chart-facts"><span><b>142</b>Median</span><span><b>189.46</b>Mean</span><span><b>869</b>Distinct values</span></div></div>'
 finding='<button class="finding-preview" data-open-finding><span class="priority">High investigation priority</span><h3>The total is already<br>in the inputs.</h3><span class="small-equation">cnt = casual + registered</span><p>One arithmetic identity, supported across the full observed overlap.</p><span class="read-finding">Read the finding <i>↗</i></span></button>'
 report_list=''.join(f'<div class="report-item"><span>{priority}</span><h3>{label}</h3><span>{desc}</span></div>' for priority,label,desc in [('High','Review the timing of the inputs.','Availability context'),('High','The total is already in the inputs.','Supported relationship'),('Moderate','Examine unusual target values.','Distribution investigation'),('Low','Interpret low variation.','Near-constant fields')])
 if n=='01':overview=title+f'<div class="work-content">{chart}{finding}</div>'
 elif n=='02':overview=f'<div class="report-cover"><span>DataTrust / Reliability report</span><h2>An account<br>of the inputs.</h2><p>Bike Sharing / Regression<br>17,379 rows. 17 columns. Four findings.</p></div><div class="report-reading"><div class="report-index">{report_list}</div>{finding}</div>'
 elif n=='03':overview=f'<div class="c-analysis-title"><h2>Bike Sharing</h2><span>Regression / Local example</span></div><div class="c-metric-band"><span><b>17,379</b>Rows examined</span><span><b>17</b>Supplied columns</span><span><b>4</b>Findings to review</span></div><div class="c-chart-band">{chart}{finding}</div>'
 elif n=='04':overview=f'<div class="focus-reading"><span>Bike Sharing / A guided reading</span><h2>Start with<br>the question.</h2><p>Are your inputs available at the moment you intend to predict?</p>{finding}</div><div class="focus-context"><span>Context / Target distribution</span>{chart}<p>17,379 finite observations. No regression score is assigned.</p></div>'
 else:overview=f'<div class="atlas-overview-title"><span>Bike Sharing / Regression</span><h2>Your investigation,<br>in view.</h2></div><div class="atlas-work-grid">{chart}<div class="atlas-source-mini"><span>Exact source / Preview</span>{T}</div>{finding}<div class="atlas-coverage"><span>Analysis scope</span><strong>17,379</strong><p>Rows in the local example.</p><span>4 findings. No regression score.</span></div></div>'
 support='<aside><strong>17,379 <span>/ 17,379</span></strong><h3>Supporting overlapping rows</h3><p>Both inputs are declared unavailable at prediction time. Review their timing and derivation against the intended feature set.</p><p>Observed equality alone does not prove leakage or actual model use.</p><button data-method>Read method and limitations</button></aside>'
 result=f'<div class="finding-title"><span>Supported target relationship</span><h2>The total is already<br>in the inputs.</h2><p>cnt = casual + registered</p></div><div class="finding-detail">{T}{support}</div>'
 if n=='04':result=f'<div class="focus-result-copy"><span>Supported target relationship</span><h2>The total<br>is already<br>in the inputs.</h2><p>cnt = casual + registered</p><button data-method>Read the method</button></div><div class="focus-result-evidence">{T}{support}</div>'
 nav='<aside class="work-nav"><span class="work-nav-label">Your analysis</span><button data-screen="overview" aria-pressed="true">Overview <span>↗</span></button><button data-screen="finding" aria-pressed="false">Findings <small>4</small></button><span class="work-nav-note">17,379 rows<br>17 columns<br>16 features</span><a href="#top">Back to NUMEK</a></aside>'
 return f'<section class="workspace" id="workspace"><header class="work-head"><span class="work-logo">{mark}DataTrust</span><span class="work-file">Bike Sharing <i>/</i> Regression</span><span class="local-label"><b></b>Local example</span><button data-method>Methods</button></header><div class="work-body">{nav}<div class="work-main"><div data-panel="overview">{overview}<div class="work-foot"><span>Other report context: input availability, IQR review candidates, near-constant fields.</span><span>No regression score is assigned.</span></div></div><div data-panel="finding" hidden>{result}</div></div></div></section>'

def end(n,concept,principle,ref):
 return f'''<section class="direction-notes" id="approach"><span>Direction {n} / {concept}</span><p>{principle}</p><a href="../research/round-03/index.html">Reference extraction & critique ↗</a></section><footer class="site-footer"><span>{mark}numek</span><p>AI reliability verification.<br>DataTrust is NUMEK’s implemented dataset analysis product.</p><span>Local visual direction proof.<br>Full prototypes follow direction review.</span></footer>'''
def write(n,title,body):
 dialog='<dialog id="methods"><button data-close>Close</button><h2>Evidence, with its limits.</h2><p>Stored regression example: Bike Sharing. The identity cnt = casual + registered holds across 17,379 overlapping rows. Both inputs are user-declared unavailable at prediction time.</p><p>These observations do not establish actual model use or prove leakage. No universal regression reliability score is defined.</p><p class="source-path">Source: validation/regression/reports/bike_hour.json</p></dialog>'
 (R/f'{n}.html').write_text(f'<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} — NUMEK</title><link rel="stylesheet" href="foundation.css"><link rel="stylesheet" href="{n}.css"></head><body class="direction-{n}" id="top">{header(n)}<main>{body}</main>{dialog}<script type="module" src="interact.js"></script></body></html>')

body='''<section class="hero"><div class="ghost-word" aria-hidden="true">numek</div><div class="volume" data-three="fold" role="img" aria-label="Sculptural interpretation of the 40-bin Bike Sharing target distribution. Use Unfold the distribution for the flat analytical plot."></div><div class="hero-statement"><h1>Reliability,<br>made visible.</h1><p>Before you train the model,<br>get to know the data.</p><a class="round-cta" href="#workspace">Explore DataTrust <span>↗</span></a></div><div class="object-note"><span class="object-dot"></span><span>The shape of one dataset.<br>40 bins. 17,379 observations.</span></div><button class="scene-control" data-unfold aria-pressed="false"><span>⊞</span> Unfold the distribution</button><div class="flat-inset" hidden>'''+P+'''<p>Bike Sharing / cnt / median 142</p></div><span class="hero-side-note">From complexity to clarity.</span></section><section class="chapter"><div><span>DataTrust by NUMEK</span><h2>Not just a pattern.<br>A place to begin.</h2></div><p>A distribution tells you what the target looks like. A finding tells you what deserves attention. DataTrust brings the two together, with the source evidence kept in view.</p><div class="chapter-pair"><div class="count-specimen"><span>Full observed overlap</span><strong>17,379</strong><span>rows support one arithmetic relationship</span></div><div class="relation-specimen"><span>Source → relationship → investigation</span><h3>cnt = casual + registered</h3><p>Review declared feature timing.<br>Equality alone does not prove leakage.</p></div></div></section>'''
write('01','Reliability, made visible',body+workspace('01')+end('01','A clearer picture','The public identity is carried by a measured data form, light and physical depth. Unfolding returns it to a flat chart; the work surface then removes perspective entirely.','Null / Micro'))

trace='''<svg class="trace-lines" viewBox="0 0 1000 620" aria-hidden="true"><path d="M440 90C520 170 160 305 370 305S600 330 720 350M60 535C200 535 160 305 370 305"/><path class="trace-highlight" d="M440 90C520 170 160 305 370 305S600 330 720 350"/><circle cx="370" cy="305" r="10"/><circle cx="720" cy="350" r="7"/></svg><svg class="trace-mobile-lines" viewBox="0 0 390 350" aria-hidden="true"><path d="M60 70C130 70 100 170 180 170S240 170 290 170M60 260C130 260 100 170 180 170"/><circle cx="180" cy="170" r="4"/></svg>'''
body='''<section class="hero"><h1>Nothing<br>on faith.</h1><div class="hero-description"><p>AI reliability begins<br>with something<br>you can trace.</p><a href="#workspace">Follow the evidence <span>↗</span></a></div><div class="trace-scene">'''+trace+'''<div class="trace-source trace-source-a"><span>Source / casual</span><b data-trace-a>3</b><span>Parsed row <i data-trace-row>1</i></span></div><div class="trace-source trace-source-b"><span>Source / registered</span><b data-trace-b>13</b></div><div class="trace-total"><span>Observed target / cnt</span><b data-trace-total>16</b><span>The source adds up.</span></div><div class="trace-equation"><span data-trace-equation>3 + 13 = 16</span><small>One row. A relationship across 17,379.</small></div></div><div class="trace-foot"><span>DataTrust connects the finding<br>to the evidence behind it.</span><button data-next-row>Trace another row <span>↻</span></button><span>Bike Sharing / regression<br>Existing report example</span></div></section><section class="chapter"><h2>Every claim.<br>A way back.</h2><div class="trace-detail"><span>Follow one finding</span><h3>The target is the sum<br>of two supplied inputs.</h3><p>That observation is worth investigating because both inputs were declared unavailable at prediction time. DataTrust keeps the observation, declaration and interpretation distinct.</p><a href="#workspace">Open the investigation ↗</a></div></section>'''
write('02','Nothing on faith',body+workspace('02')+end('02','A traceable claim','Curved paths are evidence links, not ambient decoration. The luminous orange finding is fed by two exact source values; another row changes all three together. The same signal color identifies findings in the workspace.','Phantom / Unseen'))

body='''<section class="hero"><div class="hero-opening"><h1>Before the model.<br>Understand the inputs.</h1><p>DataTrust / Dataset reliability<br>Built by NUMEK</p></div><div class="arithmetic"><div class="number-block"><span>casual <small>Input A</small></span><b data-kinetic-a>3</b></div><span class="math-sign">+</span><div class="number-block"><span>registered <small>Input B</small></span><b data-kinetic-b>13</b></div><span class="math-sign equals">=</span><div class="number-block answer"><span>cnt <small>Target</small></span><b data-kinetic-total>16</b></div></div><div class="hero-baseline"><div><strong>The answer was in the inputs.</strong><p>One arithmetic relationship. All 17,379 overlapping rows.<br>A reason to investigate the declared feature timing.</p></div><button data-next-kinetic>See the next row <span>↻</span></button><a href="#workspace">See the bigger picture <span>↗</span></a></div><div class="running-row"><span data-kinetic-row>Parsed row 1 / Bike Sharing</span><span>No universal regression score. Exact evidence instead.</span><span>Local analysis</span></div></section><section class="chapter"><h2>Good questions<br>make better models.</h2><div><p>The most useful output is sometimes the question you didn’t know to ask.</p><p>DataTrust examines distributions, relationships and declared context, then gives you findings you can inspect. This one starts with three columns.</p><span>Observed equality does not prove leakage.</span></div></section>'''
write('03','Before the model',body+workspace('03')+end('03','The answer in the inputs','Typography is the analytical specimen. Each source value occupies its own column and the target interrupts the field. Changing the row makes the relationship legible without inventing a score or verdict.','Obys / Pudding'))

matrix='<div class="matrix-head"><span>row</span><span>casual</span><span>registered</span><span>cnt</span></div>'+''.join('<div class="matrix-row">'+''.join(f'<span>{v}</span>' for v in row)+'</div>' for row in rows)
body='''<section class="hero"><div class="hero-opening"><h1>Look past<br>the surface.</h1><p>DataTrust turns dataset findings<br>into something you can examine.</p></div><div class="evidence-landscape"><div class="matrix-base">'''+matrix+'''</div><div class="lens" data-lens><div class="lens-reflection"></div><span class="lens-kicker">Source evidence / row 1</span><strong>3 + 13<br><i>= 16</i></strong><span class="lens-caption">casual + registered = cnt</span><span class="lens-cross">+</span></div><span class="landscape-caption">Five exact source rows from the Bike Sharing example.</span></div><div class="hero-baseline"><a href="#workspace">Take a closer look <span>↗</span></a><p>Inspectable findings.<br>Explainable methods.<br>Your data stays local.</p><button data-lens-next>Examine the next row <span>+</span></button></div></section><section class="chapter"><span>DataTrust by NUMEK</span><h2>A finding is only<br>the beginning.</h2><div><p>Get past the summary. Inspect the rows, understand the method, and know where the interpretation stops.</p><p>This relationship is observed across 17,379 overlapping rows. The declared prediction-time availability is a separate piece of context.</p></div></section>'''
write('04','Look past the surface',body+workspace('04')+end('04','Evidence in focus','A source table becomes the landscape. A movable optical reading surface reveals one row precisely, then the same focus-and-context relationship becomes the analytical workspace.','Micro / Obys'))

mini_hist=f'<div class="atlas-plot">{P}</div>'
body='''<section class="hero"><div class="hero-identity" aria-hidden="true">numek</div><div class="atlas-scene" data-atlas><div class="atlas-plane atlas-report"><span>DATATRUST</span><h2>Bike<br>Sharing.</h2><span>Dataset reliability<br>Regression / local report</span><div class="report-seal">4<br><small>findings</small></div></div><div class="atlas-plane atlas-distribution"><span>The shape of the target</span>'''+mini_hist+'''<div><b>142</b>median target</div></div><div class="atlas-plane atlas-source"><span>Evidence / exact source</span>'''+T+'''<span>17,379 overlapping rows</span></div><div class="atlas-plane atlas-finding"><span>High investigation priority</span><h2>The total<br>is already<br>in the inputs.</h2><p>cnt = casual + registered</p><span>Inspect source evidence ↗</span></div><div class="atlas-plane atlas-method"><span>METHOD / SCOPE</span><h2>Know what<br>the finding<br>can tell you.</h2><p>Observed equality alone does not prove leakage or model use.</p></div></div><div class="hero-baseline"><div><h1>The evidence<br>comes together.</h1><p>DataTrust by NUMEK. A wider view of dataset reliability.</p></div><button data-atlas-flat aria-pressed="false">Bring it into focus <span>⊞</span></button><a href="#workspace">Enter the workspace <span>↗</span></a></div></section><section class="chapter"><h2>One analysis.<br>Many ways in.</h2><p>Start with a finding. Read the distribution. Inspect the source rows. Return to the method. Every surface belongs to the same investigation.</p></section>'''
write('05','The evidence comes together',body+workspace('05')+end('05','A wider view','An investigation becomes a spatial composition of actual evidence, with different scales and reading distances. A single action aligns the planes. The workspace keeps this breadth through a quiet source-and-finding split.','Phantom / Micro / Obys'))
print('Built five new art-direction proofs.')
